                       data      = semdata,
                       estimator = "ML",
                       se        = "bootstrap",
                       bootstrap = 1000)

med_effects &lt;- lavaan::parameterEstimates(med_fit, boot.ci.type = "bca.simple") |&gt;
  dplyr::filter(label %in% c("a", "b", "c", "indirect", "total")) |&gt;
  dplyr::select(Label = label, Estimate = est, SE = se,
