Checking Before Re-Scraping
A simple caching pattern avoids redundant requests:


Code
scrape_with_cache &lt;- function(url, cache_dir = "cache") {
  # Create a filename from the URL
  fname &lt;- file.path(cache_dir,
                     paste0(digest::digest(url, algo = "md5"), ".rds"))

  if (file.exists(fname)) {
    message("Loading from cache: ", url)
    return(readRDS(fname))
  }

  message("Scraping: ", url)
  Sys.sleep(runif(1, 1, 2))
  page &lt;- polite::bow(url, user_agent = "LADAL tutorial scraper") |&gt;
    polite::scrape()

  saveRDS(page, fname)
  page
}

if / else statements
An if statement runs a block of code only when a condition is TRUE. The optional else block runs when it is FALSE.


Code
n_docs &lt;- nrow(corpus)

if (n_docs &gt;= 10) {
  cat("Corpus is large enough for analysis:", n_docs, "documents.\n")
} else {
  cat("Corpus may be too small:", n_docs, "documents.\n")
}


Corpus is large enough for analysis: 12 documents.


Chain multiple conditions with else if:


Code
mean_tokens &lt;- mean(corpus$n_tokens)

if (mean_tokens &lt; 10) {
  complexity &lt;- "low"
} else if (mean_tokens &lt; 15) {
  complexity &lt;- "moderate"
} else {
  complexity &lt;- "high"
}

cat("Average token count:", round(mean_tokens, 1),
    "— Complexity:", complexity, "\n")


